#!/usr/bin/env node
// Query the dsh-src code index.
// Usage: node query-code-index.mjs <substring> [--kind class|function|interface|type|const|enum|method|property] [--pkg <name>] [--limit N]
//
// Internal structure (behavior-identical to baseline-of-record source/query-code-index.mjs):
//   argParse        — flag/positional parsing, usage + exit-code contract
//   freshnessCheck  — pull-based stale detection + inline rebuild (best-effort, never blocks)
//   telemetry       — one JSONL line per query appended to usage.log (best-effort)
//   renderHits      — double-space-joined stdout rows + stderr summary

import fs from 'node:fs'
import { execSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { fileURLToPath } from 'node:url'

// ---------------------------------------------------------------------------
// argParse — flags --kind/--pkg/--limit, -h/--help, single positional substring
// ---------------------------------------------------------------------------

const usage = () => {
  console.error('usage: node query-code-index.mjs <substring> [--kind class|function|interface|type|const|enum|method|property] [--pkg <name>] [--limit N]')
}
const die = (msg, code = 1) => { console.error(msg); process.exit(code) }

const MAX_LIMIT = 200 // bounded output
const DEFAULT_LIMIT = 10
const REPO_PATH = '/workspace/dsh-src'

function argParse(argv) {
  let needle = null, kindFilter = null, pkgFilter = null, limit = DEFAULT_LIMIT
  for (let i = 0; i < argv.length; i++) {
    const token = argv[i]
    if (token === '--kind') kindFilter = argv[++i]
    else if (token === '--pkg') pkgFilter = argv[++i]
    else if (token === '--limit') limit = parseInt(argv[++i], 10)
    else if (token === '-h' || token === '--help') { usage(); process.exit(0) }
    else if (needle === null) needle = token
    else die(`unexpected argument: ${token}\n`, 2)
  }
  if (!needle) { usage(); process.exit(2) }
  if (!Number.isFinite(limit) || limit < 1) die('--limit must be a positive integer', 2)
  limit = Math.min(limit, MAX_LIMIT)
  return { needle, kindFilter, pkgFilter, limit }
}

// ---------------------------------------------------------------------------
// freshnessCheck — pull-based: if the repo moved since the build, rebuild
// inline (~2.5s) so every query serves current data even without the cron
// watchdog. Best-effort — a failed rebuild must never block a query
// (stale beats dead).
// ---------------------------------------------------------------------------

function freshnessCheck(indexPath) {
  try {
    const snapshot = JSON.parse(fs.readFileSync(indexPath, 'utf8'))
    const liveHead = execSync(`git -C ${REPO_PATH} rev-parse --short=7 HEAD`, { stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim()
    const liveDirty = createHash('sha1').update(execSync(`git -C ${REPO_PATH} status --porcelain`, { stdio: ['ignore', 'pipe', 'ignore'] }).toString()).digest('hex').slice(0, 10)
    const meta = snapshot.meta || {}
    if (meta.repoHead !== liveHead || meta.repoDirtyHash !== liveDirty) {
      console.error('-- index stale (repo moved since build); rebuilding inline... --')
      execSync('node ' + fileURLToPath(new URL('./build-code-index.mjs', import.meta.url)), { stdio: ['ignore', 'inherit', 'inherit'] })
    }
  } catch (e) {
    console.error(`-- freshness check skipped: ${e.message} --`)
  }
}

// ---------------------------------------------------------------------------
// telemetry — usage log (JSONL, one line per query), answers "is the index
// used?". Best-effort only: a logging failure must never break a query.
// ---------------------------------------------------------------------------

function telemetry(query, hitCount, elapsedMs) {
  try {
    fs.appendFileSync(
      fileURLToPath(new URL('../code-index/usage.log', import.meta.url)),
      JSON.stringify({ ts: new Date().toISOString(), sub: query, kind: query.kind, pkg: query.pkg, hits: hitCount, ms: elapsedMs }) + '\n',
    )
  } catch {}
}

// ---------------------------------------------------------------------------
// renderHits — double-space-joined rows on stdout, summary on stderr
// ---------------------------------------------------------------------------

function renderHits(matches, maxRows, totalSymbols, generatedAt) {
  if (matches.length === 0) {
    die(`no symbols matching "${matches.query}"${matches.kind ? ` [kind=${matches.kind}]` : ''}${matches.pkg ? ` [pkg=${matches.pkg}]` : ''} in index (${totalSymbols} symbols, generated ${generatedAt})`)
  }
  for (const match of matches.slice(0, maxRows)) {
    console.log([match.name, match.kind, match.pkg, `${match.file}:${match.line}`, match.doc || ''].join('  '))
  }
  console.error(`-- ${matches.length} hit(s), showing ${Math.min(maxRows, matches.length)} --`)
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------

const query = argParse(process.argv.slice(2))
const indexPath = fileURLToPath(new URL('../code-index/index.json', import.meta.url))

freshnessCheck(indexPath)

let index
try { index = JSON.parse(fs.readFileSync(indexPath, 'utf8')) } catch (e) { die(`cannot read index at ${indexPath}: ${e.message}`) }

const needleLower = query.needle.toLowerCase()
const t0 = Date.now()
const matches = index.symbols.filter((s) =>
  (!query.kind || s.kind === query.kind) &&
  (!query.pkg || s.pkg === query.pkg || s.pkg.includes(query.pkg)) &&
  s.name.toLowerCase().includes(needleLower),
)

telemetry({ ...query }, matches.length, Date.now() - t0)
renderHits(Object.assign(matches, { query: query.needle, kind: query.kind, pkg: query.pkg }), query.limit, index.symbols.length, index.generated)
